void unlinkEvent(XactLink* node) {
    node->next->previous = node->previous;
    node->previous->next = node->next;
    node->next = node;
    node->previous = node;
}

uint32_t eventHeader(const XactEvent* event) {
    // Event records belong to a packed byte stream; do not require alignment.
    uint32_t word;
    std::memcpy(&word, event->record, sizeof(word));
    return word;
}

int32_t cueOwnsTransitions(void* cue) {
    auto table = *static_cast<void***>(cue);
    return reinterpret_cast<int32_t (*)(void*)>(table[31])(cue);
}
